# NOTE (v1 MVP):
# Underwater path is generated by reversing surface coverage.
# This will be replaced by depth-aware and flow-aware planning in later versions.

import math
from typing import List, Dict, Any, Tuple

from src.common.logging import logger
from src.common.action.entity import Speeds
from src.common.entity.position import Waypoint
from src.common.projection.entity import FishFrameObject

from src.fish.stage3_action.entity import Navigation



class PathNavigator:
    """
    Helps in Fish's machine navigation. 
    """
    def __init__(self, navigation_cfg: Navigation):
        self.cfg = navigation_cfg

        self.speeds: Speeds  = self.cfg.speeds
        self.sweep_step: float = self.cfg.sweep_step
        self.current_position: Waypoint = self.cfg.start_point
        self.reach_threshold: float = self.cfg.reach_threshold                                              # To check target is in reach or not for Fish machine

        self.path: List[Waypoint] = []
        self.current_index: int = 0                                                                         # No. of waypoints crossed in the set path.
        self.curr_speed: float = self.speeds.surface
        self.dt = 1.0
        self.paused: bool = False

        self.step_count: int = 0
        self.trajectory: list[Dict[Any, Any]] = []
        self.last_fish_position: Waypoint = Waypoint(0.0, 0.0, 0.0)                           
        self.curr_fish_direction: int = 1                                                                   # Maintaining a direction flag for garbage object simulation

        self.hazard_detection_radius = 2.5
        self.hazard_safe_distance = 18.0
        self.avoidance_strength = 2.0

        self.in_avoidance_mode = False
        self.avoidance_waypoint = None
        self.avoidance_return_index = 0
        self.avoidance_offset_distance = 8.0

        self.return_waypoint = None
        self.returning_to_path = False



    def set_path(self, depth: float, start_position: Waypoint):
        try:
            logger.debug(f"PathNavigator -> set_path(): STARTS, depth: {depth}")

            # Generate SURFACE path once.
            if not self.path or len(self.path) == 0:
                self.path = self.generate_lawnmower_path(cleaning_depth = 0.0)

            # NOTE: UNDERWATER path = Reversed cached SURFACE path + project to depth.
            # SURFACE LEVEL path is generted first, then UNDERWATER LEVEL.
            if depth < 0:
                rev_surface_path = list(reversed(self.path)) 
                active_path = [Waypoint(wp.x, wp.y, depth) for wp in rev_surface_path]                                       
            else:
                active_path = self.path
             
            # Updating path parameters for the current operation level.
            self.path = active_path
            self.current_position = start_position
            self.current_index = 0                                                                          # to avoid index error if path is not generated.
            self.paused = False

            logger.debug(f"PathNavigator -> set_path(): ENDS, active path: {self.path}")
            return 


        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> set_path(), error: {e}")
            raise e



    def generate_lawnmower_path(self, cleaning_depth: float) -> List[Waypoint]:
        """
        Generates the `Lawn mower path` pattern, the chosen navigation pattern for the Fish machine.

        ONLY generates surface-style lawnmower path.
        ```
            [----------------                  
            ----------------]
            [----------------                  
            ----------------]
            [----------------                  
            ----------------]
            [----------------                  
            ----------------]

            (brackets are turns)
        ```
        
        :param self: Belongs to the PathNavigator class.
        :param cleaning_depth: Depth of workspace of current operation. 
        :type cleaning_depth: float
        :return: List of waypoint in the Lawn-mower path.
        :rtype: List[Waypoint]
        """
        try:
            logger.debug(f"PathNavigator -> generate_lawn_mower_path(): STARTS, cleaning_depth: {cleaning_depth}")
            
            path: List[Waypoint] = []

            # Defining boundary of workspace.
            x_start, y_start = self.cfg.start_point.x, self.cfg.start_point.y
            x_end, y_end = self.cfg.end_point.x, self.cfg.end_point.y

            direction: int = 1
            y_curr: float = y_start

            while y_curr <= y_end:                                              # (eg: 0 < 100, 20 < 100, 100 = 100)
                # Moving forward in x-axis
                if direction == 1:                                              
                    path.append(Waypoint(x_start, y_curr, cleaning_depth))      # x -> 0,       y -> 0
                    path.append(Waypoint(x_end, y_curr, cleaning_depth))        # x -> 100,     y -> 0

                # Moving backward in x-axis
                else:                                                           
                    path.append(Waypoint(x_end, y_curr, cleaning_depth))        # x -> 100,     y -> 5
                    path.append(Waypoint(x_start, y_curr, cleaning_depth))      # x -> 0,       y -> 5

                # Moving in y-axis, by 1 sweep step, to reach towards end point.
                y_curr += self.sweep_step    

                # Reversing the direction of fish machine.   
                direction *= -1                 
                

            logger.debug(f"PathNavigator -> generate_lawn_mower_path(): ENDS")
            return path


        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> generate_lawnmower_path(), error: {e}")
            raise e



    def pause(self):
        try:
            self.paused = True


        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> pause(), error: {e}")
            raise e


    
    def resume(self):
        try:
            self.paused = False


        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> resume(), error: {e}")
            raise e
        



    def target_is_near(self, object: FishFrameObject) -> bool:
        """
        Decide if target is close enough to execute manipulation.
        """
        try:
            logger.debug(f"PathNavigator -> target_is_near(): STARTS, fish frame object: {object}")

            target_is_near = object.relative_distance <= self.reach_threshold

            logger.debug(f"PathNavigator -> target_is_near(): ENDS, target_is_near: {target_is_near}")
            return target_is_near
        

        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> target_is_near(), error: {e}")
            raise e
    


    def get_next_position_in_path(self, hazard_objects: List[FishFrameObject]) -> Waypoint:
        """
        Navigation is the authoritative source of robot motion.

        All position updates are computed here and passed to the simulation layer for execution. 
        
        This avoids conflicting motion models and keeps planning logic centralized.
        
        :param self: Belongs to the PathNavigator class
        :param dt: The time diffrence for calculating step_distance/incremental motion
        :type dt: float
        :return: Returns confirmation where the Fish machine stepped forward or not.
        :rtype: bool
        """
        try:
            logger.info(f"PathNavigator -> get_next_position_in_path(): STARTS")
         
            # 1. Recognize the next target waypoint in the set path.
            target_waypoint = self.path[self.current_index]
            logger.info(f"PathNavigator -> get_next_position_in_path(): current index: {self.current_index}, current position: {self.current_position}, target position: {target_waypoint}")

            # 2. Calculate direction vectors (3D)
            dx = target_waypoint.x - self.current_position.x
            dy = target_waypoint.y - self.current_position.y
            dz = target_waypoint.z - self.current_position.z

            # Distance between current position and the next target waypoint(not new position)
            distance = math.sqrt(dx*dx + dy*dy + dz*dz)
            logger.info(f"PathNavigator -> get_next_position_in_path(): Distance between current position and next target waypoint: {distance}")

            # 3. Compute step distance, using formula [distance = speed * time]
            step_distance = self.curr_speed * self.dt

            # 4. If already reached very close to target waypoint and might overshoot in stepping, then snap to target waypoint and then approach next waypoint.
            if distance <= step_distance:
                
                # Snap to the current target first
                self.current_position = target_waypoint   
                self.log_trajectory_point()                                                                 # To avoid missing logging the snapped waypoint

                # Advance the current index
                self.current_index += 1

                # Check if path is finished, then return the last current position / target waypoint, to avoid index out of range error.
                if self.path_is_finished():                                                                 # refer ACTION_NOTES.md(9)
                    logger.info(f"PathNavigator -> get_next_position_in_path(): Current set path is finished, returning current position")
                    return self.current_position                            

                # If current path is not finished, then set the next waypoint in the path as target.
                target_waypoint = self.path[self.current_index]             

                # Calculate direction vectors (3D) again for the new target.
                dx = target_waypoint.x - self.current_position.x
                dy = target_waypoint.y - self.current_position.y
                dz = target_waypoint.z - self.current_position.z

                distance = math.sqrt(dx*dx + dy*dy + dz*dz)
                logger.info(f"PathNavigator -> get_next_position_in_path(): New distance between current and target: {distance}")


            # 5. Normalize goal directions
            ux = dx / distance
            uy = dy / distance
            uz = dz / distance

            logger.info(f"PathNavigator -> Direction vectors, before adding avoidance vector: {(ux, uy, uz)}")

            # Adding repulsive avoidance vector in case of navigation hazard is present                     # refer ACTION_NOTE.md(14)
            if len(hazard_objects) > 0:
                self.create_avoidance_waypoint(hazard_objects=hazard_objects)

            if self.in_avoidance_mode:
                avoidance_position = self.handle_avoidance_navigation()
                
                if avoidance_position is not None:
                    logger.info("Returning avoidance navigation position")
                    return avoidance_position
    
            
            # 6. Incremental motion
            new_x = self.current_position.x + ux * step_distance
            new_y = self.current_position.y + uy * step_distance
            new_z = self.current_position.z + uz * step_distance

            # 7. New position for Fish machine
            new_position = Waypoint(new_x, new_y, new_z)

            # 8. Find Fish machine's current navigation direction (USED IN SIMULATION, garbage spawning)
            self.update_fish_direction(fish_delta_x = dx)
            
            logger.info(f"PathNavigator -> get_next_position_in_path(): ENDS, new_position: {new_position}")
            return new_position
        
        
        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> get_next_position_in_path(), error: {e}")
            raise e



    def handle_avoidance_navigation(self):
        try:

            if not self.in_avoidance_mode or self.avoidance_waypoint is None:
                return None

            dx = (
                self.avoidance_waypoint.x -
                self.current_position.x
            )

            dy = (
                self.avoidance_waypoint.y -
                self.current_position.y
            )

            dz = (
                self.avoidance_waypoint.z -
                self.current_position.z
            )

            distance = math.sqrt(
                dx * dx +
                dy * dy +
                dz * dz
            )

            if distance < 2.0:

                # Reached bypass waypoint
                if not self.returning_to_path:

                    logger.info(
                        "Reached bypass waypoint, returning to path"
                    )

                    self.avoidance_waypoint = self.return_waypoint

                    self.returning_to_path = True

                    return None

                # Reached return waypoint
                logger.info(
                    "Returned to original traversal path"
                )
 
                self.in_avoidance_mode = False

                self.returning_to_path = False

                self.current_index = self.avoidance_return_index

                return None

            ux = dx / distance
            uy = dy / distance
            uz = dz / distance

            step_distance = self.curr_speed * self.dt

            new_x = (
                self.current_position.x +
                ux * step_distance
            )

            new_y = (
                self.current_position.y +
                uy * step_distance
            )

            new_z = (
                self.current_position.z +
                uz * step_distance
            )

            new_position = Waypoint(
                new_x,
                new_y,
                new_z
            )

            logger.info(
                f"Avoidance navigation active, new position: {new_position}"
            )

            return new_position

        except Exception as e:

            logger.exception(
                f"handle_avoidance_navigation(): exception: {e}"
            )

            return None
    


    def create_avoidance_waypoint(
        self,
        hazard_objects: List[FishFrameObject]
    ) -> None:

        try:

            if len(hazard_objects) == 0:
                return

            if self.in_avoidance_mode:
                return

            logger.info(
                "create_avoidance_waypoint(): STARTS"
            )

            nearest_hazard = hazard_objects[0]

            # Fish-frame → world-frame conversion
            hazard_world_x = -nearest_hazard.relative_position.y
            hazard_world_y = -nearest_hazard.relative_position.x

            logger.info(
                f"Converted hazard position: {(hazard_world_x, hazard_world_y)}"
            )

            # Current mission direction
            target_waypoint = self.path[self.current_index]

            dx = target_waypoint.x - self.current_position.x
            dy = target_waypoint.y - self.current_position.y

            distance = math.sqrt(dx * dx + dy * dy)

            if distance < 0.01:
                return

            ux = dx / distance
            uy = dy / distance

            # Perpendicular left vector
            perp_x = -uy
            perp_y = ux

            # Decide avoidance side using hazard position
            side = 1.0

            if hazard_world_y > 0:
                side = -1.0

            bypass_x = (
                self.current_position.x +
                ux * 2.0 +
                perp_x * self.avoidance_offset_distance * side
            )

            bypass_y = (
                self.current_position.y +
                uy * 2.0 +
                perp_y * self.avoidance_offset_distance * side
            )

            bypass_z = self.current_position.z

            self.avoidance_waypoint = Waypoint(
                bypass_x,
                bypass_y,
                bypass_z
            )

            # Return point ahead on original path
            return_x = self.current_position.x + ux * 30.0

            return_y = self.current_position.y + uy * 30.0

            return_z = self.current_position.z

            self.return_waypoint = Waypoint(
                return_x,
                return_y,
                return_z
            )

            self.in_avoidance_mode = True

            self.avoidance_return_index = self.current_index

            logger.info(
                f"Created avoidance waypoint: {self.avoidance_waypoint}"
            )

        except Exception as e:

            logger.exception(
                f"create_avoidance_waypoint(): exception: {e}"
            )



    def path_is_finished(self) -> bool:
        try:
            logger.debug(f"PathNavigator -> path_is_finished(): STARTS")

            path_is_finished = self.current_index >= len(self.path)

            logger.info(f"PathNavigator -> path_is_finished(): ENDS, path_is_finished: {path_is_finished}")
            return path_is_finished
        

        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> path_is_finished(), error: {e}")
            raise e

     

    # NOTE: Can be refactored into TrajectoryLogger service in future
    def log_trajectory_point(self):
        try:
            logger.debug(f"PathNavigator -> log_trajectory_point(): STARTS")

            # Determining the operation level of the Fish machine
            operation_level = "surface" if self.current_position.z >= 0 else "underwater"

            self.trajectory.append({
                "current_position": self.current_position,
                "operation_level": operation_level,
                "step_taken": self.step_count
            })

            logger.debug(f"PathNavigator -> log_trajectory_point(): ENDS")
            return


        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> log_trajectory_point(), error: {e}")
            raise e
        



    def update_fish_direction(self, fish_delta_x: float) -> None:
        try:
            logger.debug(f"PathNavigator -> update_fish_direction(): STARTS, curr_pos: {self.current_position}, last_pos: {self.last_fish_position}")

            # Updating current direction of Fish machine
            logger.info(f"PathNavigator -> update_fish_direction(), fish_delta_x: {fish_delta_x}")

            # Determining direction of fish machine
            if fish_delta_x > 0:
                curr_dir = 1
            elif fish_delta_x < 0:
                curr_dir = -1
            else:
                curr_dir = 0

            self.curr_fish_direction = curr_dir

            # NOTE:
            # If dir =  1, then fish moving in [0   ->  100] direction in x-axis and
            # if dir = -1, then fish moving in [100 ->   0] direction in x-axis
            # If dir =  0, then fish moving in y-axis

            # Updating fish machine's last position as the current position
            self.last_fish_position = self.current_position

            logger.info(f"PathNavigator -> update_fish_direction(): ENDS, current DIRECTION: {self.curr_fish_direction}")
            return


        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> update_fish_direction(), error: {e}")
            raise e



    def is_reached_destination(self, target_position: Waypoint) -> bool:
        try:
            is_reached = False
            if self.current_position == target_position:
                is_reached = True
            
            logger.info(f"PathNavigator -> is_reached_destination(): ENDS, is_reached: {is_reached}") 
            return is_reached


        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> is_reached_destination(), error: {e}")
            raise e
        


    def get_linear_step_to_destination(self, destination: Waypoint) -> Waypoint:
        try:
            logger.debug(f"PathNavigator -> get_linear_step_to_destination(): STARTS")

            # 1. Calculate direction vectors (3D), for DIRECT destination
            dx = destination.x - self.current_position.x
            dy = destination.y - self.current_position.y
            dz = destination.z - self.current_position.z

            # Distance between current position and the destination
            distance = math.sqrt(dx*dx + dy*dy + dz*dz)
            logger.info(f"PathNavigator -> get_linear_step_to_destination(): Distance between current position and destination: {distance}")

            # 2. Compute step distance, using formula [distance = speed * time]
            step_distance = self.curr_speed * self.dt

            # 3. If already reached very close to target waypoint and might overshoot in stepping, then snap to target waypoint and then approach next waypoint.
            if distance <= step_distance:
                
                # Snap to the current target first
                self.current_position = destination   
                self.log_trajectory_point()                                                                 # To avoid missing logging the snapped waypoint
                
                logger.info(f"PathNavigator -> get_linear_step_to_destination(): Destination reached") 
                return destination                                                                                        
    

            # 4. Normalize directions
            ux = dx / distance
            uy = dy / distance
            uz = dz / distance

            # 5. Incremental motion
            new_x = self.current_position.x + ux * step_distance
            new_y = self.current_position.y + uy * step_distance
            new_z = self.current_position.z + uz * step_distance

            # 7. New position for Fish machine
            new_position = Waypoint(new_x, new_y, new_z)            

            logger.info(f"PathNavigator -> get_linear_step_to_destination(): ENDS, new_position: {new_position}")
            return new_position


        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> get_linear_step_to_destination(), error: {e}")
            raise e



    def compute_hazard_avoidance_vector(self, hazards: List[FishFrameObject]) -> Tuple[float,float]:
        try:
            logger.info(f"compute_hazard_avoidance_vector(): STARTS, hazard objects: {hazards}")
            
            avoid_x = 0.0
            avoid_y = 0.0

            for hazard in hazards:

                # Fish-frame → world-frame conversion
                hazard_world_x = -hazard.relative_position.y                         # refer src/common/simulation/constants.py (line 20)
                hazard_world_y = -hazard.relative_position.x
                logger.info(f"After frame conversion, before pos: {hazard.relative_position}, after pos: {(hazard_world_x, hazard_world_y)}")

                # Relative obstacle direction
                hx = -hazard_world_x
                hy = -hazard_world_y
                
                hazard_distance = math.sqrt(hx*hx + hy*hy)

                # ignoring distanct hazard
                if hazard_distance > self.hazard_detection_radius:
                    logger.info(f"distance is greater than hazard detection radius, distance: {hazard_distance}")
                    continue

                # prevent divide by 0 error
                if hazard_distance < 0.01:
                    logger.info(f"distance is less than 0.01, distance: {hazard_distance}")
                    hazard_distance = 0.01
                
                # Dynamic influence scaling, stronger repulsion when closer
                influence = self.avoidance_strength * (1 - (hazard_distance / self.hazard_detection_radius))

                # Repulsion vector
                repel_x = hx
                repel_y = hy

                tangent_x = -hy
                tangent_y = hx

                avoid_x += (0.05 * repel_x + 1.8 * tangent_x) * influence
                avoid_y += (0.05 * repel_y + 1.8 * tangent_y) * influence


            avoidance_vector = (avoid_x, avoid_y)
            logger.info(f"compute_hazard_avoidance_vector(), avoidance_vector: {avoidance_vector}")

            return avoidance_vector


        except Exception as e:
            logger.error(f"Error occurred in PathNavigator -> compute_hazard_avoidance_vector(), error: {e}")
            raise e